// Shared set-up of the picture bench tests (#340): the invented "Kestrel Row Bike Workshop", its kit (written to a
// temporary contract folder with its content map, so the bench reads it like a shipped kit), plan and brief, and owner
// photos generated by code (_generated-photos.mjs): no real photo, no customer data. No real model is called: every run
// has the looker door assigned (#343, a run does not start without it), and its looks are answered by a fake that
// passes every picture; the drawer door is assigned too (#344), and its drawings are answered by a fake that draws a
// flat picture of a colour taken from the request (a cut-out drawing, #346: a code drawn figure on the plain ground it
// asked for).
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import path from 'node:path'
import sharp from 'sharp'
import { assignDoor, saveProvider } from '../src/lib/llm-store.js'
import { startPictureRun } from '../src/site-pictures/bench-control.js'
import { createSitePicturesQueue } from '../src/site-pictures/bench-worker.js'
import { scene } from './_generated-photos.mjs'

export const KIT_REF = 'demo-bikes/j6/1.0.0'
/** The secret the test doors' keys are sealed with. */
export const SECRET = 's'.repeat(32)
/** The looker's model in the tests. */
export const LOOKER_MODEL = 'openai/gpt-6-luna'
/** The drawer's model in the tests, and what one drawing costs. */
export const DRAWER_MODEL = 'google/gemini-3.1-flash-lite-image'
export const DRAW_COST = 0.034
export const quiet = { error() {}, warn() {}, log() {} }
const sha = (bytes) => createHash('sha256').update(bytes).digest('hex')

const frame = (id, kind, width, height, extra = {}) => ({
  id,
  kind,
  width,
  height,
  shape: { name: 'any', aspect: Math.round((width / height) * 1000) / 1000 },
  canHide: true,
  twinOf: null,
  fixed: false,
  picture: `images/demo/${id}.jpg`,
  role: null,
  ...extra
})
const slot = (key, width, height) => ({
  key,
  type: 'image',
  sample: `images/demo/${key}.jpg#joomlaImage://local-images/demo/${key}.jpg?width=${width}&height=${height}`,
  fit: { source: { width, height, format: 'jpg' } }
})

