/** The content map beside the kit: the demo file sizes the write door compares with. */
export const contentMap = () => ({
  slots: [
    slot('module-2.0', 800, 400),
    slot('module-3.1', 300, 300),
    slot('module-3.2', 300, 300),
    slot('module-3.3', 300, 300),
    slot('module-3.4', 300, 300),
    slot('module-4.1', 240, 300),
    slot('module-4.2', 240, 300),
    slot('module-5.1', 400, 300),
    slot('module-5.2', 400, 300),
    slot('module-6.1', 450, 300),
    slot('module-6.9', 450, 300),
    slot('module-9.0', 400, 300),
    slot('module-9.1', 64, 64),
    slot('module-9.2', 300, 300)
  ]
})

/** A contract index holding the invented kit and its content map, in a temporary folder; `done()` removes it. */
export function kitIndex() {
  const dir = mkdtempSync(path.join(tmpdir(), 'site-pictures-kit-'))
  writeFileSync(path.join(dir, 'template-kit.json'), JSON.stringify(kit()))
  writeFileSync(path.join(dir, 'content-map.json'), JSON.stringify(contentMap()))
  return {
    index: new Map([['demo-bikes@1.0.0', { id: KIT_REF, dir, platform: 'joomla' }]]),
    done: () => rmSync(dir, { recursive: true, force: true })
  }
}

/** A temporary file store folder; `done()` removes it. */
export function storeDir() {
  const dir = mkdtempSync(path.join(tmpdir(), 'site-pictures-store-'))
  return { dir, done: () => rmSync(dir, { recursive: true, force: true }) }
}

// The owner photos, generated by code: id -> [palette, width, height, labels].
const PHOTOS = {
  'p-repair-desk': ['bakery', 1600, 1000, { depicts: { id: 'f-repair', evidence: { via: 'vision' } } }],
  'p-wheels': ['dental', 1200, 900, { depicts: { id: 'f-wheels', evidence: { via: 'vision' } } }],
  'p-shopfront': ['bakery', 1000, 800, {}],
  'p-tools': ['dental', 1300, 800, {}],
  'p-small': ['dental', 360, 300, { quality: 'low' }],
  'p-owner': [
    'dental',
    800,
    1000,
    { portraitOf: { id: 'f-owner', evidence: { via: 'alt' } }, faceBoxes: [[0.35, 0.15, 0.3, 0.25]] }
  ],
  'p-sign': ['bakery', 1400, 900, { hasTextOrWatermark: true }],
  'p-blurry': ['dental', 1400, 900, { isBlurry: true }]
}

/** Every owner photo as bytes, by id, generated once. */
export const PHOTO_BYTES = new Map(
  await Promise.all(
    Object.entries(PHOTOS).map(async ([id, [palette, w, h]]) => [id, await scene(palette, w, h, id.length)])
  )
)

const asset = (id, bytes, width, height, extra) => ({
  id,
  kind: 'image',
  category: 'other',
  sha256: sha(bytes),
  width,
  height,
  quality: 'high',
  isBlurry: false,
  hasTextOrWatermark: false,
  showsOtherBusiness: false,
  isOwnPhoto: true,
  portraitOf: null,
  subjectBox: [0.25, 0.2, 0.5, 0.6],
  faceBoxes: [],
  ...extra
})

export function brief() {
  const fact = (id, field, value) => ({ id, field, value, source: 'stated' })
  return {
    language: 'en',
    facts: [
      fact('f-name', 'name', 'Kestrel Row Bike Workshop'),
      fact('f-repair', 'offering', 'Bike repair'),
      fact('f-wheels', 'offering', 'Wheel building'),
      fact('f-owner', 'team', 'Mara Quill, owner'),
      fact('f-mechanic', 'team', 'Theo Brandt, mechanic')
    ],
    assets: [
      ...Object.entries(PHOTOS).map(([id, [, w, h, extra]]) => asset(id, PHOTO_BYTES.get(id), w, h, extra)),
      { id: 'v-tour', kind: 'video', category: 'other', sha256: 'f'.repeat(64), unlabelledReason: 'video' }
    ]
  }
}

const wish = (frameId, match, extra = {}) => ({
  frame: frameId,
  kind: 'photo',
  match,
  size: 'as the kit',
  shows: 'a mechanic truing a wheel on the stand',
  mustInclude: ['wheel'],
  avoid: ['lettering'],
  mood: 'calm',
  factIds: [],
  ...extra
})
const keep = (block, extra = {}) => ({ block, seen: 'seen', decision: 'keep', why: 'fits', ...extra })

/** The plan every frame of which code can decide: any-real, person, twins, hide, not writable, site settings. */
export function plan({ later = false } = {}) {
  return {
    version: 'site-plan/3',
    kit: `tracy-template-kit/2 ${KIT_REF}`,
    site: { name: 'Kestrel Row Bike Workshop' },
    sharedBlocks: [keep('block-1')],
    pages: [
      {
        id: 'page-home',
        decision: 'keep',
        blocks: [
          keep('block-2', { pictures: [wish('block-2.0', 'any-real', { factIds: ['f-repair'] })] }),
          keep('block-3', {
            lists: [
              {
                list: 'block-3.item',
                rows: 4,
                items: ['3.1', '3.2', '3.3', '3.4'].map((n) => ({
                  about: 'the workshop',
                  pictures: [wish(`block-${n}`, 'any-real')]
                }))
              }
            ]
          }),
          keep('block-4', {
            pictures: [
              wish('block-4.1', 'person', { person: 'f-owner', shows: 'head and shoulders' }),
              wish('block-4.2', 'person', { person: 'f-mechanic', shows: 'head and shoulders' })
            ]
          }),
          keep('block-6', { pictures: [wish('block-6.1', 'any-real', { factIds: ['f-wheels'] })] })
        ]
      },
      {
        id: 'page-about',
        decision: 'keep',
        blocks: [
          keep('block-5', {
            pictures: [
              wish('block-5.1', 'any-real'),
              { frame: 'block-5.2', kind: 'photo', sameAs: 'block-5.1' }
            ]
          }),
          keep('block-7', { pictures: [wish('block-7.picture-1', 'any-real')] }),
          keep('block-8', { pictures: [wish('block-8.1', 'any-real')] }),
          ...(later
            ? [
                keep('block-9', {
                  pictures: [
                    wish('block-9.0', 'specific', { shows: 'the owner fitting a tyre' }),
                    wish('block-9.1', 'specific', { kind: 'icon', shows: 'a spanner' }),
                    wish('block-9.2', 'specific', { kind: 'cutout', shows: 'a rider with a bike' })
                  ]
                })
              ]
            : [])
        ]
      }
    ]
  }
}

/** The owner photo folder a CLI run on a brief file reads: every photo named by its hash. */
export const photoFolder = () => ({
  name: 'kestrel-photos',
  files: new Map([...PHOTO_BYTES.values()].map((bytes) => [`${sha(bytes)}.jpg`, bytes]))
})

/** The looker door on gpt-6-luna through OpenRouter. */
export async function assignLookerDoor(pool, model = LOOKER_MODEL) {
  await saveProvider(
    pool,
    { id: 'openrouter', presetId: 'openrouter', apiKey: 'sk-test-looker-key', enabled: true },
    SECRET,
    'owner@tracy.test'
  )
  await assignDoor(pool, 'pictureLooker', { providerId: 'openrouter', model }, 'owner@tracy.test')
}

/** The drawer door on gemini flash lite image through OpenRouter. */
export async function assignDrawerDoor(pool, model = DRAWER_MODEL) {
  await saveProvider(
    pool,
    { id: 'openrouter', presetId: 'openrouter', apiKey: 'sk-test-looker-key', enabled: true },
    SECRET,
    'owner@tracy.test'
  )
  await assignDoor(pool, 'pictureDrawer', { providerId: 'openrouter', model }, 'owner@tracy.test')
}

/** Whether a request body is a drawing: only the drawer asks for an image answer. */
export const isDraw = (body) => Array.isArray(body?.modalities) && body.modalities.includes('image')

/** The text of a drawing request. */
export const drawText = (body) => {
  const c = body.messages[0].content
  return typeof c === 'string' ? c : c.find((p) => p.type === 'text').text
}

/** The plain ground a cut-out drawing asks for (#346), or null. */
export const groundAsked = (body) =>
  /plain background of one single colour:\s*[^(]*\((#[0-9a-f]{6})\)/.exec(drawText(body))?.[1] ?? null

/**
 * A code drawn figure (a body, a head, a racket with thin strings) standing in the middle of a picture on a flat
 * ground; `figure` its main colour.
 */
export function figureOnGround(ground, { width = 1024, height = 576, figure = '#c8323c' } = {}) {
  const cx = width / 2
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">
    <rect width="${width}" height="${height}" fill="${ground}"/>
    <ellipse cx="${cx}" cy="${height * 0.62}" rx="${height * 0.16}" ry="${height * 0.3}" fill="${figure}"/>
    <circle cx="${cx}" cy="${height * 0.24}" r="${height * 0.09}" fill="#f4f4f0"/>
    <ellipse cx="${cx + height * 0.3}" cy="${height * 0.4}" rx="${height * 0.09}" ry="${height * 0.13}" fill="none" stroke="#1a1a1a" stroke-width="4"/>
    <line x1="${cx + height * 0.3}" y1="${height * 0.27}" x2="${cx + height * 0.3}" y2="${height * 0.53}" stroke="#f4f4f0" stroke-width="2"/>
  </svg>`
  return sharp(Buffer.from(svg)).png().toBuffer()
}

/**
 * A drawer answer as OpenRouter sends it: one flat picture (its colour from the request text, so two frames never get
 * the same file, unless `colour` is given) and the call's cost. A cut-out drawing gets a figure on the ground it asked
 * for (its colour from the request text too), unless `colour` is given.
 */
export async function drawReply(body, { colour = null, cost = DRAW_COST, width = 1024, height = 576 } = {}) {
  const h = createHash('sha256')
    .update(JSON.stringify(body ?? null))
    .digest()
  const background = colour ?? { r: 60 + (h[0] % 120), g: 60 + (h[1] % 120), b: 60 + (h[2] % 120) }
  const ground = colour ? null : groundAsked(body)
  const png = ground
    ? await figureOnGround(ground, {
        width,
        height,
        figure: `#${[160 + (h[0] % 60), 30 + (h[1] % 40), 30 + (h[2] % 40)].map((v) => v.toString(16)).join('')}`
      })
    : await sharp({ create: { width, height, channels: 3, background } })
        .png()
        .toBuffer()
  return new Response(
    JSON.stringify({
      model: DRAWER_MODEL,
      choices: [
        {
          message: {
            role: 'assistant',
            content: '',
            images: [
              { type: 'image_url', image_url: { url: `data:image/png;base64,${png.toString('base64')}` } }
            ]
          }
        }
      ],
      usage: { prompt_tokens: 300, completion_tokens: 1300, cost }
    }),
    { headers: { 'content-type': 'application/json' } }
  )
}

/** Whether a request body is a look: the looker's user message holds the picture; no other step sends one there. */
export const isLook = (body) =>
  Array.isArray(body?.messages?.[1]?.content) &&
  body.messages[1].content.some((p) => p.type === 'image_url') &&
  /looker/.test(String(body.messages[0]?.content))

/** A looker answer: `said` ({ verdict, faults, seen }) by default passes, at no cost. */
export const lookReply = (
  said = { verdict: 'pass', faults: [], seen: 'A mechanic at work in a workshop.' },
  cost = 0
) =>
  new Response(
    JSON.stringify({
      model: LOOKER_MODEL,
      choices: [{ message: { role: 'assistant', content: JSON.stringify(said) } }],
      usage: { prompt_tokens: 900, completion_tokens: 40, cost }
    }),
    { headers: { 'content-type': 'application/json' } }
  )

/** A fetch that answers every look with a pass, every drawing with a flat picture, and hands every other request to `other`. */
export const passingLooker = (other) => async (url, init) => {
  const body = init?.body ? JSON.parse(init.body) : null
  if (isLook(body)) return lookReply()
  if (isDraw(body)) return drawReply(body)
  return other(url, init)
}

/** Start a run on a brief file and its photo folder, with the looker door assigned; fails the test when refused. */
export async function startRun(pool, { index, dir }, over = {}) {
  const { keepDoors, ...rest } = over
  if (!keepDoors) {
    await assignLookerDoor(pool)
    await assignDrawerDoor(pool)
  }
  const started = await startPictureRun({
    secret: SECRET,
    pool,
    plan: plan(),
    planSource: { kind: 'file', name: 'kestrel-plan.json' },
    brief: brief(),
    briefSource: { kind: 'file', name: 'kestrel-brief.json' },
    kitRef: KIT_REF,
    startedBy: 'cli',
    photos: photoFolder(),
    storeDir: dir,
    index,
    ...rest
  })
  assert.equal(started.ok, true, JSON.stringify(started))
  return started.run
}

/** A fake model door that passes every look and fails the test if anything else is called: a code only run calls no
 * other model. */
export const noModel = passingLooker(async (url) => {
  throw new Error(`a code only picture run called ${url}`)
})

/** Run what is queued with one worker. */
export async function drain(pool, { index, dir, fetchImpl = noModel }) {
  await createSitePicturesQueue({
    pool,
    secret: SECRET,
    index,
    storeDir: dir,
    fetchImpl,
    balanceFetch: fetchImpl,
    log: quiet
  })
    .drain()
    .catch(() => {})
}

/** The pixel size of stored bytes. */
export const sizeOf = async (bytes) => {
  const m = await sharp(bytes).metadata()
  return { width: m.width, height: m.height }
}
